import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  redirect,
  createMemoryHistory,
} from '@tanstack/react-router';

let isAuthed = false;
export function setAuthed(v: boolean) {
  isAuthed = v;
}

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

export const loginRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/login',
  component: () => <p>please log in</p>,
});

export const profileRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/profile',
  beforeLoad: () => {
    if (!isAuthed) throw redirect({ to: '/login' });
  },
  component: () => <p>welcome</p>,
});

const routeTree = rootRoute.addChildren([loginRoute, profileRoute]);

export function makeRouter(initialEntries: string[] = ['/profile']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
